#!/usr/bin/env bash
# СНИМОК серверного /home/deploy/deploy.sh (для видимости главного пути деплоя).
#
# Зачем файл здесь: @TL 07:25 — «deploy.sh вообще отсутствует в репозитории, хотя его
# вызывают update.sh и оба ранбука; значит аудит 7-deploy/** проверял не то, что
# исполняется». Этот файл делает главный путь видимым и диффабельным.
#
# ВАЖНО:
#   * пароли БД в снимке заменены на __REDACTED__ (репозиторий публичный);
#   * настоящие секреты — только в secrets/.env на сервере;
#   * полный перенос на compose-деплой из репозитория — задача DO-049 (ротация паролей).
#   * снимок НЕ исполняется напрямую: источник истины пока серверный файл.
#!/usr/bin/env bash
set -euo pipefail
TAG="${1:-single}"
cd /opt/xdiary/7-deploy
NET=xdiary
LBL='--label io.containers.autoupdate=registry'
for x in $(podman ps -aq 2>/dev/null); do [ "$x" = "$(podman ps -aq --filter name=xdiary-pg)" ] || podman rm -f $x >/dev/null 2>&1; done
podman run -d --name xdiary-journal --network $NET --ip 10.89.9.20 --hostname journal $LBL --env-file secrets/.env -e "ConnectionStrings__CommandDb=Host=10.89.9.10;Port=5432;Database=journal;Username=journal;Password=__REDACTED__" -e "ConnectionStrings__ReadDb=Host=10.89.9.10;Port=5432;Database=journal;Username=journal;Password=__REDACTED__" -e ASPNETCORE_ENVIRONMENT=Single --memory 256m --pids-limit 512 --read-only --tmpfs /tmp --restart unless-stopped ghcr.io/ekstrem/xdiary-journal:$TAG >/dev/null
podman run -d --name xdiary-partners --network $NET --ip 10.89.9.21 --hostname partners $LBL --env-file secrets/.env -e "ConnectionStrings__CommandDb=Host=10.89.9.10;Port=5432;Database=partners;Username=partners;Password=__REDACTED__" -e "ConnectionStrings__ReadDb=Host=10.89.9.10;Port=5432;Database=partners;Username=partners;Password=__REDACTED__" -e ASPNETCORE_ENVIRONMENT=Single --memory 256m --pids-limit 512 --read-only --tmpfs /tmp --restart unless-stopped ghcr.io/ekstrem/xdiary-partners:$TAG >/dev/null
podman run -d --name xdiary-catalog --network $NET --ip 10.89.9.22 --hostname catalog $LBL --env-file secrets/.env -e "ConnectionStrings__CommandDb=Host=10.89.9.10;Port=5432;Database=catalog;Username=catalog;Password=__REDACTED__" -e "ConnectionStrings__ReadDb=Host=10.89.9.10;Port=5432;Database=catalog;Username=catalog;Password=__REDACTED__" -e ASPNETCORE_ENVIRONMENT=Single --memory 256m --pids-limit 512 --read-only --tmpfs /tmp --restart unless-stopped ghcr.io/ekstrem/xdiary-catalog:$TAG >/dev/null
podman run -d --name xdiary-somatic-series --network $NET --ip 10.89.9.23 --hostname somatic-series $LBL --env-file secrets/.env -e "ConnectionStrings__CommandDb=Host=10.89.9.10;Port=5432;Database=somatic_series;Username=somatic_series;Password=__REDACTED__" -e "ConnectionStrings__ReadDb=Host=10.89.9.10;Port=5432;Database=somatic_series;Username=somatic_series;Password=__REDACTED__" -e ASPNETCORE_ENVIRONMENT=Single --memory 256m --pids-limit 512 --read-only --tmpfs /tmp --restart unless-stopped ghcr.io/ekstrem/xdiary-somatic-series:$TAG >/dev/null
podman run -d --name xdiary-daily-metrics --network $NET --ip 10.89.9.24 --hostname daily-metrics $LBL --env-file secrets/.env -e "ConnectionStrings__CommandDb=Host=10.89.9.10;Port=5432;Database=daily_metrics;Username=daily_metrics;Password=__REDACTED__" -e "ConnectionStrings__ReadDb=Host=10.89.9.10;Port=5432;Database=daily_metrics;Username=daily_metrics;Password=__REDACTED__" -e ASPNETCORE_ENVIRONMENT=Single --memory 256m --pids-limit 512 --read-only --tmpfs /tmp --restart unless-stopped ghcr.io/ekstrem/xdiary-daily-metrics:$TAG >/dev/null
podman run -d --name xdiary-garmin-gateway --network $NET --ip 10.89.9.25 --hostname garmin-gateway $LBL --env-file secrets/.env -e "ConnectionStrings__CommandDb=Host=10.89.9.10;Port=5432;Database=garmin_gateway;Username=garmin_gateway;Password=__REDACTED__" -e "ConnectionStrings__ReadDb=Host=10.89.9.10;Port=5432;Database=garmin_gateway;Username=garmin_gateway;Password=__REDACTED__" -e ASPNETCORE_ENVIRONMENT=Single --memory 256m --pids-limit 512 --read-only --tmpfs /tmp --restart unless-stopped ghcr.io/ekstrem/xdiary-garmin-gateway:$TAG >/dev/null
podman run -d --name xdiary-apple-health-gateway --network $NET --ip 10.89.9.26 --hostname apple-health-gateway $LBL --env-file secrets/.env -e "ConnectionStrings__CommandDb=Host=10.89.9.10;Port=5432;Database=apple_health_gateway;Username=apple_health_gateway;Password=__REDACTED__" -e "ConnectionStrings__ReadDb=Host=10.89.9.10;Port=5432;Database=apple_health_gateway;Username=apple_health_gateway;Password=__REDACTED__" -e ASPNETCORE_ENVIRONMENT=Single --memory 256m --pids-limit 512 --read-only --tmpfs /tmp --restart unless-stopped ghcr.io/ekstrem/xdiary-apple-health-gateway:$TAG >/dev/null
podman run -d --name xdiary-analytics --network $NET --ip 10.89.9.27 --hostname analytics $LBL --env-file secrets/.env -e "ConnectionStrings__CommandDb=Host=10.89.9.10;Port=5432;Database=analytics;Username=analytics;Password=__REDACTED__" -e "ConnectionStrings__ReadDb=Host=10.89.9.10;Port=5432;Database=analytics;Username=analytics;Password=__REDACTED__" -e ASPNETCORE_ENVIRONMENT=Single --memory 256m --pids-limit 512 --read-only --tmpfs /tmp --restart unless-stopped ghcr.io/ekstrem/xdiary-analytics:$TAG >/dev/null
podman run -d --name xdiary-privacy --network $NET --ip 10.89.9.28 --hostname privacy $LBL --env-file secrets/.env -e "ConnectionStrings__CommandDb=Host=10.89.9.10;Port=5432;Database=privacy;Username=privacy;Password=__REDACTED__" -e "ConnectionStrings__ReadDb=Host=10.89.9.10;Port=5432;Database=privacy;Username=privacy;Password=__REDACTED__" -e ASPNETCORE_ENVIRONMENT=Single --memory 256m --pids-limit 512 --read-only --tmpfs /tmp --restart unless-stopped ghcr.io/ekstrem/xdiary-privacy:$TAG >/dev/null
podman run -d --name xdiary-portability --network $NET --ip 10.89.9.29 --hostname portability $LBL --env-file secrets/.env -e "ConnectionStrings__CommandDb=Host=10.89.9.10;Port=5432;Database=portability;Username=portability;Password=__REDACTED__" -e "ConnectionStrings__ReadDb=Host=10.89.9.10;Port=5432;Database=portability;Username=portability;Password=__REDACTED__" -e ASPNETCORE_ENVIRONMENT=Single --memory 256m --pids-limit 512 --read-only --tmpfs /tmp --restart unless-stopped ghcr.io/ekstrem/xdiary-portability:$TAG >/dev/null
podman run -d --name xdiary-client --network $NET --ip 10.89.9.31 --hostname client $LBL --env-file secrets/.env -e "ConnectionStrings__CommandDb=Host=10.89.9.10;Port=5432;Database=client;Username=client;Password=__REDACTED__" -e "ConnectionStrings__ReadDb=Host=10.89.9.10;Port=5432;Database=client;Username=client;Password=__REDACTED__" -e ASPNETCORE_ENVIRONMENT=Single --memory 256m --pids-limit 512 --read-only --tmpfs /tmp --restart unless-stopped ghcr.io/ekstrem/xdiary-client:$TAG >/dev/null
podman run -d --name xdiary-api-gateway --network $NET --ip 10.89.9.30 --hostname api-gateway --add-host journal:10.89.9.20 --add-host partners:10.89.9.21 --add-host catalog:10.89.9.22 --add-host somatic-series:10.89.9.23 --add-host daily-metrics:10.89.9.24 --add-host garmin-gateway:10.89.9.25 --add-host apple-health-gateway:10.89.9.26 --add-host analytics:10.89.9.27 --add-host privacy:10.89.9.28 --add-host portability:10.89.9.29 --add-host clients:10.89.9.31 $LBL --env-file secrets/.env -e ASPNETCORE_ENVIRONMENT=Single --memory 256m --pids-limit 512 --read-only --tmpfs /tmp --restart unless-stopped -p 127.0.0.1:8080:8080 ghcr.io/ekstrem/xdiary-api-gateway:$TAG >/dev/null
